-- es 공식 계정(pinwith_es)·예시 계정·예시 리스트 4개. 먼저 seed_lang_loader.sql을 실행해 둘 것.
select private.seed_lang_examples('es', 'es', $doc${"official":{"display_name":"PinWith Oficial","bio":"Listas hechas por el equipo de PinWith para inspirar tu próximo viaje."},"samples":[{"display_name":"Usuario de ejemplo 1","bio":"Cuenta de ejemplo creada por PinWith para mostrar cómo un grupo de amigos planea un viaje juntos."},{"display_name":"Usuario de ejemplo 2","bio":"Cuenta de ejemplo creada por PinWith para mostrar cómo un grupo de amigos planea un viaje juntos."},{"display_name":"Usuario de ejemplo 3","bio":"Cuenta de ejemplo creada por PinWith para mostrar cómo un grupo de amigos planea un viaje juntos."}],"lists":[{"role":"plain","owner":"official","slug":"madrid-imprescindible","kind":"course","title":"Madrid imprescindible a pie","desc":"Un recorrido clásico de oeste a este: del Palacio Real al Retiro pasando por la Plaza Mayor y el Paseo del Arte. Se hace cómodamente en un día con calzado cómodo.","themes":["Madrid","paseo","museos","primera vez","a pie"],"sections":[{"name":"Madrid de los Austrias","by":"official","items":[{"place_id":"ChIJwamkfX4oQg0RUUjO1nnsfy4","title":"Palacio Real","memo":"Llega a primera hora para evitar filas; si no entras, la explanada de la Plaza de la Armería ya vale la pena.","tags":["palacio","historia"],"lat":40.417955,"lng":-3.714312},{"place_id":"ChIJ7aLeH4EoQg0RzT0PTqYc3Y4","title":"Campo del Moro","memo":"Los jardines detrás del palacio, mucho más tranquilos que el centro; la vista del palacio desde abajo es la mejor foto.","tags":["jardín","tranquilo"],"lat":40.418262,"lng":-3.717295},{"place_id":"ChIJZX56134oQg0RHBgRAVQ8pkk","title":"Plaza Mayor","memo":"Ideal para ver la plaza, pero mejor come el bocadillo de calamares en los bares de las calles de alrededor que en las terrazas.","tags":["plaza","bocadillo de calamares"],"lat":40.415511,"lng":-3.707401}]},{"name":"Paseo del Arte","by":"official","items":[{"place_id":"ChIJ7aLYZp0oQg0RWoitk33wlBA","title":"Museo del Prado","memo":"Elige de antemano unas pocas salas (Velázquez, Goya, El Bosco); las últimas dos horas del día la entrada es gratuita y hay mucha fila.","tags":["museo","arte"],"lat":40.413782,"lng":-3.692127},{"place_id":"ChIJv-yiGoMoQg0Rj1LLgnhKk1o","title":"Museo Thyssen","memo":"Colección muy variada, del Renacimiento al pop art; es más manejable que el Prado si tienes poco tiempo.","tags":["museo","arte"],"lat":40.416041,"lng":-3.694925},{"place_id":"ChIJ34M6wYIoQg0RpdMzyZ_IGcc","title":"Paseo del Prado","memo":"El bulevar arbolado que une los museos; perfecto para caminar a la sombra entre una visita y otra.","tags":["paseo","sombra"],"lat":40.41758,"lng":-3.693691},{"place_id":"ChIJMyYo0M8pQg0Rfdp3Zk32aDQ","title":"Paisaje de la Luz (Cibeles)","memo":"Zona declarada Patrimonio Mundial; sube al mirador del Palacio de Cibeles para ver la Gran Vía desde arriba.","tags":["patrimonio","mirador"],"lat":40.418934,"lng":-3.692152}]},{"name":"El Retiro","by":"official","items":[{"place_id":"ChIJe4IR9Z8oQg0RrqMktRYnbJ4","title":"Parque del Retiro","memo":"Termina el día en el estanque grande alquilando una barca; no te pierdas el Palacio de Cristal.","tags":["parque","atardecer"],"lat":40.415258,"lng":-3.683466},{"place_id":"ChIJQ5ZUtp0oQg0RInkmVIXJAzQ","title":"Casón del Buen Retiro","memo":"Parte del Prado; abre para exposiciones y visitas puntuales, revisa antes si está abierto para ver su techo pintado.","tags":["arte","joya escondida"],"lat":40.415282,"lng":-3.689601}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-tulum-riviera-maya-cenotes","kind":"course","title":"[Vlog] Tulum y la Riviera Maya: ruta de cenotes","desc":"Un día largo de ruinas y cenotes entre Tulum y Playa del Carmen, con los mejores momentos para grabar y nadar sin multitudes.","themes":["Tulum","cenotes","Riviera Maya","vlog","fotografía"],"sections":[{"name":"Amanecer en Tulum","by":"official","items":[{"place_id":"ChIJc6wA0WPRT48RtsvIzCP19lA","title":"Zona arqueológica de Tulum","memo":"En el video arranco justo a la apertura: el castillo sobre el mar con luz suave y sin gente es el plano del día. Lleva agua y sombrero.","tags":["ruinas","amanecer","sin gente"],"lat":20.212536,"lng":-87.435631},{"place_id":"ChIJ_xjkInTUT48Rit_t2yqp8M4","title":"Gran Cenote","memo":"Ven temprano para ver las tortugas y los rayos de luz entrando al agua; es obligatorio ducharse y no usar bloqueador normal.","tags":["snorkel","tortugas"],"lat":20.246582,"lng":-87.464201},{"place_id":"ChIJ05R00_nTT48RP0Id3KOhDBk","title":"Cenote Calavera","memo":"Los tres agujeros parecen una calavera; el salto desde arriba queda épico en cámara lenta.","tags":["salto","cámara lenta"],"lat":20.227878,"lng":-87.458044}]},{"name":"Hacia Cobá","by":"official","items":[{"place_id":"ChIJE-0-RfDUT48RsTrw8ZxWqxQ","title":"Cenote Zacil-Ha","memo":"Cenote abierto con tirolesa sobre el agua; buen lugar para descansar y comer algo entre grabaciones.","tags":["tirolesa","relax"],"lat":20.274397,"lng":-87.48835},{"place_id":"ChIJ2e8-eH3RT48Rp47UfBct888","title":"Casa Cenote (Manatí)","memo":"Agua cristalina entre manglares, casi a la orilla del mar; perfecto para tomas de drone o GoPro a ras del agua.","tags":["manglar","GoPro"],"lat":20.216169,"lng":-87.428277}]},{"name":"Rumbo a Playa del Carmen","by":"official","items":[{"place_id":"ChIJ3bHaTUUtTo8R6FlVhvaTBzE","title":"Cenote Dos Ojos","memo":"Para la toma de cueva necesitas linterna o luz de buceo; con guía puedes pasar de un 'ojo' al otro.","tags":["cueva","buceo"],"lat":20.325006,"lng":-87.390814},{"place_id":"ChIJB3zWJkctTo8Rn9Nvn7vkguM","title":"Cenotes Sac Actún","memo":"Uno de los sistemas de cuevas inundadas más largos del mundo; el recorrido guiado vale cada minuto de batería.","tags":["cueva","tour guiado"],"lat":20.3182,"lng":-87.41057},{"place_id":"ChIJOwStV4U3To8RqmN9lJ2o114","title":"Cenote Azul","memo":"Cierro el vlog aquí por la tarde: poco profundo, ideal para nadar tranquilo y grabar los peces.","tags":["familiar","tarde"],"lat":20.488169,"lng":-87.25102}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"barcelona-finde-largo-amigos","kind":"collection","title":"Finde largo en Barcelona con amigos","desc":"Tres amigos armando cuatro días en Barcelona: cada uno agregó sus imprescindibles. El plan final quedó en los comentarios de la Barceloneta.","themes":["Barcelona","Gaudí","amigos","fin de semana","playa"],"sections":[{"name":"Lo de Gaudí sí o sí","by":"ex1","items":[{"place_id":"ChIJk_s92NyipBIRUMnDG8Kq2Js","title":"Sagrada Família","memo":"Hay que reservar con días de anticipación; la luz de los vitrales es mejor por la tarde.","tags":["Gaudí","reservar"],"lat":41.40363,"lng":2.174356},{"place_id":"ChIJq0HUUq6ipBIRWM6qGqALmok","title":"Park Güell","memo":"La zona monumental requiere entrada con horario; está en subida, así que mejor ir en metro o bus y no a pie desde el centro.","tags":["Gaudí","vistas"],"lat":41.414495,"lng":2.152694}]},{"name":"Paseo por el centro","by":"ex2","items":[{"place_id":"ChIJYUFLSe2ipBIRD04uni940kA","title":"Casa Batlló","memo":"En pleno Paseo de Gràcia; aunque no entremos, la fachada de noche iluminada es preciosa.","tags":["Gaudí","fachada"],"lat":41.3917,"lng":2.164918},{"place_id":"ChIJg2xxlvmipBIRg1jhdSQR9hY","title":"Catedral de Barcelona","memo":"Puerta de entrada al Barrio Gótico; se puede subir a la terraza para ver los tejados.","tags":["gótico","terraza"],"lat":41.383962,"lng":2.176199}]},{"name":"Comer y playa","by":"ex3","items":[{"place_id":"ChIJAVoetfeipBIR1a1z3FTGCoY","title":"La Boqueria","memo":"Mejor por la mañana, antes de que se llene; los puestos del fondo suelen ser más baratos que los de la entrada.","tags":["mercado","tapas"],"lat":41.38174,"lng":2.171585},{"place_id":"ChIJJ5Y4CaijpBIR-2VJP9cOjh4","title":"Barceloneta","memo":"Playa urbana a un paseo del Gótico; cuidado con las mochilas en la arena.","tags":["playa","atardecer"],"lat":41.378371,"lng":2.192468}]}],"comments":[{"place_id":"ChIJk_s92NyipBIRUMnDG8Kq2Js","by":"ex1","body":"Chicos, las entradas de la Sagrada Família se agotan. ¿La compro ya para el viernes por la tarde?","replies":[{"by":"ex2","body":"Sí, porfa. Por la tarde mejor, que llegamos el viernes en la mañana y vamos a estar muertos."},{"by":"ex3","body":"Con la subida a las torres no, que es más cara. Solo la básica y ya."}]},{"place_id":"ChIJq0HUUq6ipBIRWM6qGqALmok","by":"ex2","body":"Park Güell también pide horario. ¿El sábado temprano?","replies":[{"by":"ex1","body":"Va, a primera hora. Luego bajamos a Gràcia a desayunar."}]},{"place_id":"ChIJAVoetfeipBIR1a1z3FTGCoY","by":"ex3","body":"Propongo desayunar en la Boqueria el domingo y de ahí caminar a la Catedral, está cerquísima.","replies":[{"by":"ex2","body":"Me encanta. Ojo que algunos puestos cierran temprano o no abren todos los días."},{"by":"ex1","body":"Entonces vamos el sábado después del Park Güell y el domingo dejamos el día libre."}]},{"place_id":"ChIJYUFLSe2ipBIRD04uni940kA","by":"ex2","body":"¿Entramos a Casa Batlló o solo la vemos por fuera? Está caro.","replies":[{"by":"ex3","body":"Por fuera de noche y ese dinero lo gastamos en vermut jaja."},{"by":"ex1","body":"De acuerdo, solo fachada."}]},{"place_id":"ChIJJ5Y4CaijpBIR-2VJP9cOjh4","by":"ex1","body":"Plan final: vie tarde Sagrada Família → noche Paseo de Gràcia (Casa Batlló por fuera). Sáb temprano Park Güell → Boqueria → Catedral y Gótico. Dom libre y Barceloneta para el atardecer. Lun nos vamos.","replies":[{"by":"ex2","body":"Perfecto. Si llueve el domingo, cambiamos playa por museo."},{"by":"ex3","body":"Aprobado. Yo llevo la toalla grande para los tres."}]}]},{"role":"food","owner":"official","slug":"cdmx-ruta-de-tacos","kind":"course","title":"Ruta de tacos en la Ciudad de México","desc":"Del Centro Histórico a Coyoacán: taquerías legendarias y un mercado para cerrar. Ve con hambre y en pequeñas dosis: dos o tres tacos por parada.","themes":["CDMX","tacos","comida callejera","mercados"],"sections":[{"name":"Centro Histórico","by":"official","items":[{"place_id":"ChIJ_6pkSM3-0YURDDaRslwM_0w","title":"Zócalo","memo":"Punto de partida de la ruta; desde aquí son pocas cuadras caminando a Los Cocuyos.","tags":["punto de partida"],"lat":19.432642,"lng":-99.133321},{"place_id":"ChIJs1uZdNP-0YUR7xEuCTGxAMM","title":"Los Cocuyos","memo":"Puesto mítico de tacos de suadero y campechanos; se come de pie y abre hasta muy tarde.","tags":["suadero","de pie","noche"],"lat":19.430279,"lng":-99.138798}]},{"name":"San Rafael, Condesa y Roma","by":"official","items":[{"place_id":"ChIJDdgBq8_40YUReV5XNsJFMJE","title":"El Califa de León","memo":"Taquería pequeñita y famosísima por su taco de gaonera; espera fila y lugar solo de pie.","tags":["gaonera","leyenda"],"lat":19.441046,"lng":-99.159231},{"place_id":"ChIJXQJPPWr_0YURVCvnKidKKUU","title":"El Califa (Condesa)","memo":"La sucursal original de la cadena, con mesas para sentarte; pide la costra de queso.","tags":["sentado","costra"],"lat":19.40636,"lng":-99.172537},{"place_id":"ChIJyarBHtD_0YURDBZerKnqrNA","title":"El Califa (Roma)","memo":"Buena opción si andas paseando por la Roma; útil de noche cuando otras taquerías ya cerraron.","tags":["Roma","noche"],"lat":19.417338,"lng":-99.162697}]},{"name":"Coyoacán","by":"official","items":[{"place_id":"ChIJOz-6AMT_0YURofTM9_ekAWI","title":"Casa Azul (Museo Frida Kahlo)","memo":"Compra boletos en línea con anticipación y haz la visita antes de comer en el mercado.","tags":["museo","reservar"],"lat":19.355181,"lng":-99.162464},{"place_id":"ChIJeYLOZMT_0YURFEhp2ubb43c","title":"Mercado de Coyoacán","memo":"A unas cuadras de la Casa Azul; famoso por sus tostadas, ideal para cerrar la ruta.","tags":["tostadas","mercado"],"lat":19.352737,"lng":-99.161637}]}],"comments":[]}]}$doc$::jsonb);
